<?php
// Read input
$line = trim(fgets(STDIN));
list($n, $m, $a, $b) = explode(' ', $line);
$n = (int)$n;
$m = (int)$m;
$a = (int)$a;
$b = (int)$b;

// We need to find the minimum cost for n rides.
// Option 1: Buy all single tickets: n * a
// Option 2: Buy some m-ride tickets and some single tickets.
// Let k be the number of m-ride tickets. Then we need max(0, n - k*m) single tickets.
// Total cost = k * b + max(0, n - k * m) * a
// k can range from 0 to ceil(n / m)

$minCost = PHP_INT_MAX;

// Maximum number of m-ride tickets we might need
$maxK = (int)ceil($n / $m);

for ($k = 0; $k <= $maxK; $k++) {
    $ridesCovered = $k * $m;
    $remainingRides = max(0, $n - $ridesCovered);
    $cost = $k * $b + $remainingRides * $a;
    if ($cost < $minCost) {
        $minCost = $cost;
    }
}

echo $minCost . "\n";
?>
